using System.Windows;
using System.Windows.Controls;
namespace DomainConsole;
public sealed class StopChoice:Window {
 public string Mode {get;private set;}="now";
 public StopChoice(Window owner,string computer,bool forceAvailable){Owner=owner;Title="Остановка · "+computer;Width=480;SizeToContent=SizeToContent.Height;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;var panel=new StackPanel{Margin=new(18)};panel.Children.Add(new TextBlock{Text="Остановить задание только на "+computer,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap});var now=new RadioButton{Content="Сейчас — отправить Ctrl+C",IsChecked=true,Margin=new(0,14,0,8)};var after=new RadioButton{Content="После текущей команды",Margin=new(0,0,0,10)};panel.Children.Add(now);panel.Children.Add(after);RadioButton? force=null;if(forceAvailable){force=new RadioButton{Content="Принудительно завершить процессы команды",Margin=new(0,0,0,10)};panel.Children.Add(force);}panel.Children.Add(new TextBlock{Text="Встроенные операции обновления и восстановления останавливаются в безопасной точке. Принудительное завершение доступно отдельным действием, если текстовая команда не завершилась после Ctrl+C.",TextWrapping=TextWrapping.Wrap,Foreground=System.Windows.Media.Brushes.SlateGray});var actions=new WrapPanel{Margin=new(0,16,0,0)};var ok=new Button{Content="Остановить",Background=System.Windows.Media.Brushes.Firebrick,Foreground=System.Windows.Media.Brushes.White,Padding=new(14,8,14,8),IsDefault=true};ok.Click+=(s,e)=>{Mode=force?.IsChecked==true?"force":after.IsChecked==true?"after":"now";DialogResult=true;};var cancel=new Button{Content="Отмена",IsCancel=true,Margin=new(8,0,0,0),Padding=new(14,8,14,8)};actions.Children.Add(ok);actions.Children.Add(cancel);panel.Children.Add(actions);Content=panel;}
}
